<template>
  <div class="page category-page">
    <!-- 页面头部 -->
    <div class="page-header flex-between">
      <el-button type="text" icon="el-icon-arrow-left" @click="$router.back()" />
      <span>分类管理</span>
      <el-button type="text" @click="showAddDialog">新增</el-button>
    </div>

    <!-- 分类列表 -->
    <div class="cat-list">
      <div
        v-for="cat in categories"
        :key="cat.id"
        class="cat-item"
      >
        <div class="cat-info">
          <span class="cat-color" :style="{ backgroundColor: cat.color }"></span>
          <span class="cat-name">{{ cat.name }}</span>
          <span class="cat-count">{{ getItemCount(cat.id) }} 件</span>
        </div>
        <div class="cat-actions">
          <el-button type="text" size="small" @click="editCat(cat)">编辑</el-button>
          <el-button
            type="text"
            size="small"
            class="text-danger"
            @click="deleteCat(cat)"
            :disabled="getItemCount(cat.id) > 0"
          >
            删除
          </el-button>
        </div>
      </div>
    </div>

    <!-- 空状态 -->
    <div v-if="categories.length === 0" class="empty-state">
      <div class="empty-icon">🏷️</div>
      <p>暂无分类</p>
    </div>

    <!-- 新增/编辑弹窗 -->
    <el-dialog
      :title="editMode ? '编辑分类' : '新增分类'"
      :visible.sync="dialogVisible"
      width="300px"
    >
      <el-form :model="catForm" label-position="top">
        <el-form-item label="分类名称">
          <el-input v-model="catForm.name" placeholder="如：衣服、化妆品" />
        </el-form-item>
        <el-form-item label="颜色">
          <div class="color-picker">
            <span
              v-for="c in colorOptions"
              :key="c"
              class="color-swatch"
              :class="{ active: catForm.color === c }"
              :style="{ backgroundColor: c }"
              @click="catForm.color = c"
            ></span>
          </div>
        </el-form-item>
      </el-form>
      <span slot="footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="saveCat">确定</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import {
  loadCategories,
  addCategory,
  saveCategories,
  isCategoryInUse
} from '@/store/index'
import { loadItems } from '@/store/index'
import store from '@/store/index'

export default {
  name: 'CategoryManage',
  data() {
    return {
      categories: [],
      dialogVisible: false,
      editMode: false,
      editingId: null,
      catForm: {
        name: '',
        color: '#42b983'
      },
      colorOptions: [
        '#42b983', '#f0b27a', '#5c9ded', '#e74c3c',
        '#9b59b6', '#1abc9c', '#e67e22', '#3498db',
        '#e91e63', '#8bc34a', '#ff5722', '#607d8b'
      ]
    }
  },
  created() {
    this.loadData()
  },
  methods: {
    loadData() {
      this.categories = store.loadCategories()
    },

    getItemCount(catId) {
      const items = store.loadItems()
      return items.filter(i => i.typeId === catId).length
    },

    showAddDialog() {
      this.editMode = false
      this.editingId = null
      this.catForm = { name: '', color: '#42b983' }
      this.dialogVisible = true
    },

    editCat(cat) {
      this.editMode = true
      this.editingId = cat.id
      this.catForm = { name: cat.name, color: cat.color }
      this.dialogVisible = true
    },

    saveCat() {
      if (!this.catForm.name.trim()) {
        this.$message.warning('请输入分类名称')
        return
      }

      if (this.editMode) {
        // 更新现有分类
        const cats = store.loadCategories()
        const idx = cats.findIndex(c => c.id === this.editingId)
        if (idx >= 0) {
          cats[idx].name = this.catForm.name.trim()
          cats[idx].color = this.catForm.color
          store.saveCategories(cats)
          this.$message.success('修改成功')
        }
      } else {
        // 新增分类
        store.addCategory(this.catForm.name.trim(), this.catForm.color)
        this.$message.success('添加成功')
      }

      this.dialogVisible = false
      this.loadData()
    },

    deleteCat(cat) {
      if (store.isCategoryInUse(cat.id)) {
        this.$message.warning('该分类下有物品，无法删除')
        return
      }

      this.$confirm(`确定要删除分类「${cat.name}」吗？`, '删除分类', {
        confirmButtonText: '删除',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        store.deleteCategory(cat.id)
        this.loadData()
        this.$message.success('删除成功')
      }).catch(() => {})
    }
  }
}
</script>

