ialog\n      :title=\"editMode ? '编辑分类' : '新增分类'\"\n      :visible.sync=\"dialogVisible\"\n      width=\"300px\"\n    >\n      <el-form :model=\"catForm\" label-position=\"top\">\n        <el-form-item label=\"分类名称\">\n          <el-input v-model=\"catForm.name\" placeholder=\"如：衣服、化妆品\" />\n        </el-form-item>\n        <el-form-item label=\"颜色\">\n          <div class=\"color-picker\">\n            <span\n              v-for=\"c in colorOptions\"\n              :key=\"c\"\n              class=\"color-swatch\"\n              :class=\"{ active: catForm.color === c }\"\n              :style=\"{ backgroundColor: c }\"\n              @click=\"catForm.color = c\"\n            ></span>\n          </div>\n        </el-form-item>\n      </el-form>\n      <span slot=\"footer\">\n        <el-button @click=\"dialogVisible = false\">取消</el-button>\n        <el-button type=\"primary\" @click=\"saveCat\">确定</el-button>\n      </span>\n    </el-dialog>\n  </div>\n</template>\n\n<script>\nimport {\n  loadCategories,\n  addCategory,\n  saveCategories,\n  isCategoryInUse\n} from '@/store/index'\nimport { loadItems } from '@/store/index'\nimport store from '@/store/index'\n\nexport default {\n  name: 'CategoryManage',\n  data() {\n    return {\n      categories: [],\n      dialogVisible: false,\n      editMode: false,\n      editingId: null,\n      catForm: {\n        name: '',\n        color: '#42b983'\n      },\n      colorOptions: [\n        '#42b983', '#f0b27a', '#5c9ded', '#e74c3c',\n        '#9b59b6', '#1abc9c', '#e67e22', '#3498db',\n        '#e91e63', '#8bc34a', '#ff5722', '#607d8b'\n      ]\n    }\n  },\n  created() {\n    this.loadData()\n  },\n  methods: {\n    loadData() {\n      this.categories = store.loadCategories()\n    },\n\n    getItemCount(catId) {\n      const items = store.loadItems()\n      return items.filter(i => i.typeId === catId).length\n    },\n\n    showAddDialog() {\n      this.editMode = false\n      this.editingId = null\n      this.catForm = { name: '', color: '#42b983' }\n      this.dialogVisible = true\n    },\n\n    editCat(cat) {\n      this.editMode = true\n      this.editingId = cat.id\n      this.catForm = { name: cat.name, color: cat.color }\n      this.dialogVisible = true\n    },\n\n    saveCat() {\n      if (!this.catForm.name.trim()) {\n        this.$message.warning('请输入分类名称')\n        return\n      }\n\n      if (this.editMode) {\n        // 更新现有分类\n        const cats = store.loadCategories()\n        const idx = cats.findIndex(c => c.id === this.editingId)\n        if (idx >= 0) {\n          cats[idx].name = this.catForm.name.trim()\n          cats[idx].color = this.catForm.color\n          store.saveCategories(cats)\n          this.$message.success('修改成功')\n        }\n      } else {\n        // 新增分类\n        store.addCategory(this.catForm.name.trim(), this.catForm.color)\n        this.$message.success('添加成功')\n      }\n\n      this.dialogVisible = false\n      this.loadData()\n    },\n\n    deleteCat(cat) {\n      if (store.isCategoryInUse(cat.id)) {\n        this.$message.warning('该分类下有物品，无法删除')\n        return\n      }\n\n      this.$confirm(`确定要删除分类「${cat.name}」吗？`, '删除分类', {\n        confirmButtonText: '删除',\n        cancelButtonText: '取消',\n        type: 'warning'\n      }).then(() => {\n        store.deleteCategory(cat.id)\n        this.loadData()\n        this.$message.success('删除成功')\n      }).catch(() => {})\n    }\n  }\n}\n</script>\n\n<style scoped>\n.cat-list {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.cat-item {\n  background-color: var(--bg-card);\n  border-radius: 12px;\n  padding: 14px 16px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  box-shadow: var(--shadow);\n}\n\n.cat-info {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.cat-color {\n  width: 14px;\n  height: 14px;\n  border-radius: 50%;\n  flex-shrink: 0;\n}\n\n.cat-name {\n  font-size: 15px;\n  font-weight: 500;\n  color: var(--text-primary);\n}\n\n.cat-count {\n  font-size: 12px;\n  color: var(--text-placeholder);\n  background-color: var(--bg-secondary);\n  padding: 2px 8px;\n  border-radius: 8px;\n}\n\n.cat-actions {\n  display: flex;\n  gap: 8px;\n}\n\n.color-picker {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.color-swatch {\n  width: 28px;\n  height: 28px;\n  border-radius: 50%;\n  cursor: pointer;\n  border: 2px solid transparent;\n  transition: transform 0.2s;\n}\n\n.color-swatch:hover {\n  transform: scale(1.15);\n}\n\n.color-swatch.active {\n  border-color: #333;\n  transform: scale(1.15);\n}\n</style>\n"],"sourceRoot":""}]);
